BEGIN; UPDATE public.companies c SET email = u.email FROM auth.users u WHERE c.user_id = u.id AND c.email IS NULL; CREATE OR REPLACE FUNCTION public.handle_new_user() RETURNS TRIGGER AS  DECLARE v_invitation_id UUID; v_role TEXT; v_invitation_record RECORD; BEGIN BEGIN INSERT INTO public.profiles (user_id, full_name, phone, document) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'full_name', ''), COALESCE(NEW.raw_user_meta_data->>'phone', ''), COALESCE(NEW.raw_user_meta_data->>'document', '')) ON CONFLICT (user_id) DO UPDATE SET full_name = EXCLUDED.full_name, phone = EXCLUDED.phone, document = EXCLUDED.document; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Erro ao criar perfil no signup: %', SQLERRM; END; BEGIN IF (NEW.raw_user_meta_data->>'invitation_id') IS NOT NULL THEN v_invitation_id := (NEW.raw_user_meta_data->>'invitation_id')::UUID; SELECT * INTO v_invitation_record FROM public.invitations WHERE id = v_invitation_id AND status IN ('pending', 'accepted'); IF v_invitation_record.id IS NOT NULL THEN v_role := v_invitation_record.role; BEGIN INSERT INTO public.user_roles (user_id, role) VALUES (NEW.id, v_role::public.app_role) ON CONFLICT (user_id, role) DO NOTHING; EXCEPTION WHEN OTHERS THEN NULL; END; IF v_role = 'driver' THEN BEGIN INSERT INTO public.delivery_drivers (user_id, is_online, full_name, phone) VALUES (NEW.id, false, COALESCE(NEW.raw_user_meta_data->>'full_name', 'Entregador'), COALESCE(NEW.raw_user_meta_data->>'phone', '')) ON CONFLICT (user_id) DO UPDATE SET full_name = EXCLUDED.full_name, phone = EXCLUDED.phone; EXCEPTION WHEN OTHERS THEN NULL; END; BEGIN INSERT INTO public.motoboys (name, is_online) VALUES (COALESCE(NEW.raw_user_meta_data->>'full_name', 'Novo Entregador'), false); EXCEPTION WHEN OTHERS THEN NULL; END; ELSIF v_role = 'company' THEN BEGIN INSERT INTO public.companies (user_id, name, phone, email) VALUES (NEW.id, COALESCE(NEW.raw_user_meta_data->>'company_name', v_invitation_record.email), COALESCE(NEW.raw_user_meta_data->>'phone', ''), NEW.email); EXCEPTION WHEN OTHERS THEN NULL; END; END IF; UPDATE public.invitations SET status = 'accepted', accepted_at = now() WHERE id = v_invitation_id; END IF; END IF; EXCEPTION WHEN OTHERS THEN RAISE WARNING 'Erro ao processar convite no signup: %', SQLERRM; END; RETURN NEW; END;  LANGUAGE plpgsql SECURITY DEFINER SET search_path = public; COMMIT;
